INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8806, 64551, 'tt3468798', NULL, 'Baskets', 'Baskets', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/kkbttiaCH1brriYAoBFVvNHHOcn.jpg', 'https://image.tmdb.org/t/p/original/jHh3HpkESZVKi9pCMt5GFaC4uXx.jpg', 'Chip Baskets wants to follow his dream of being a French clown—however, reality keeps interfering. Saddled with financial difficulties and facing an impenetrable language barrier, he moves back home to Bakersfield with high hopes. There, he is forced to confront his past while working as a rodeo clown and competing with his siblings for his mother''s approval and affection.', NULL, NULL, 9.9814, 6.935, 0, 9.02, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
