INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8808, 74879, 'tt1827487', NULL, 'Once Upon a Time in Anatolia', 'Bir Zamanlar Anadolu''da', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/bN84guFndgvtWIvFC7sTD8AAJDE.jpg', 'https://image.tmdb.org/t/p/original/213Gdu9zjGsVeWQl6p5gJrBq8n8.jpg', 'A group of men lead a search for a victim of a murder to whom a suspect named Kenan and his mentally challenged brother confessed. However, the search is proving more difficult than expected as Kenan is fuzzy as to the body''s location. As the group continues looking and the night begins dragging on, its members can''t help but chat with each other about everyday life, as the conversations turn more and more serious, revealing their deeper secrets and profound stories.', NULL, NULL, 2.7099, 7.475, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8809, 10779, 'tt0116365', NULL, 'The Frighteners', 'The Frighteners', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/zcJbCMwFLJdn5OLjhYwMVaSB32R.jpg', 'https://image.tmdb.org/t/p/original/krR08gys45BTnY3qXIfBJVDKrvK.jpg', 'Once an architect, Frank Bannister now passes himself off as an exorcist of evil spirits. To bolster his facade, he claims his "special" gift is the result of a car accident that killed his wife. But what he does not count on is more people dying in the small town where he lives. As he tries to piece together the supernatural mystery of these killings, he falls in love with the wife of one of the victims and deals with a crazy FBI agent.', NULL, NULL, 5.7844, 6.967, 0, 10.035, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
