INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8811, 39890, 'tt0053719', NULL, 'The City of the Dead', 'The City of the Dead', 'movie', 1960, 'https://image.tmdb.org/t/p/w500/xdM3QYjzzjuMy0cqlDNfet1BQhL.jpg', 'https://image.tmdb.org/t/p/original/bL5RTR6JXRc2tEjbTsUbGxem8gU.jpg', 'In Whitewood, Massachusetts, a presumed witch places a curse on the town before she is burned at the stake. 300 years later, a college student arrives and checks into the mysterious Raven''s Inn to research the town''s history with witchcraft.', NULL, NULL, 2.0474, 6.465, 0, 7.13, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
