INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8814, 17187, 'tt0283530', NULL, 'The Emperor''s Club', 'The Emperor''s Club', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/s7BRKAq0DNcXe8Bphm6Wd5KnvlF.jpg', 'https://image.tmdb.org/t/p/original/9gkHxp86xWGsBn6CzdChc4XhT5r.jpg', 'William Hundert is a passionate and principled Classics professor who finds his tightly-controlled world shaken and inexorably altered when a new student, Sedgewick Bell, walks into his classroom. What begins as a fierce battle of wills gives way to a close student-teacher relationship, but results in a life lesson for Hundert that will still haunt him a quarter of a century later.', NULL, NULL, 2.6018, 7.115, 0, 1.03, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8815, 38606, 'tt0061122', NULL, 'The Trouble with Angels', 'The Trouble with Angels', 'movie', 1966, 'https://image.tmdb.org/t/p/w500/bv0yTpB2so7mtjG7VIbZyfuJaO1.jpg', 'https://image.tmdb.org/t/p/original/sClW2k65ENUYOhoO2JsFRPj90Qw.jpg', 'Mary and her friend, Rachel, are new students at St. Francis Academy, a boarding school run by the iron fist of Mother Superior. The immature teens grow bored and begin playing pranks on both the unsuspecting nuns and their unpleasant classmates, becoming a constant thorn in Mother Superior''s side. However, as the years pass, Mary and Rachel slowly mature and begin to see the nuns in a different light.', NULL, NULL, 2.0706, 6.737, 0, 1.03, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
