INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8817, 12568, 'tt0412536', NULL, 'Brideshead Revisited', 'Brideshead Revisited', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/q1IqGWVNIRcXnfw9vjye7oQYUg4.jpg', 'https://image.tmdb.org/t/p/original/yXF89vOhQeGl4ayy1jez67zTPHd.jpg', 'Befriended by aristocrat Sebastian Flyte, Oxford student Charles Ryder finds that the power and privilege experienced by the family is seductive. On a visit to the ancestral home, Brideshead, he falls in love with his friend''s sister, Julia.  However, as his ties to the Flytes deepen, Ryder finds himself at odds with their strong Roman Catholicism.', NULL, NULL, 4.2931, 6.254, 0, 1.04, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
