INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8831, 372355, 'tt4991660', NULL, 'The Black Hen', 'कालो पोथी', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/ffYITYNxVYmREsaI5B6u8CE7LAn.jpg', 'https://image.tmdb.org/t/p/original/mxbiTbMNz3XnbMlPqIUDy7Do86M.jpg', 'We are in the year 2001, a temporary ceasefire brings a much-needed break to a small war-torn village in Northern Nepal, bringing much joy among the residents. Prakash and Kiran, two young close friends, are also starting to feel the change in the air. Though they are divided by caste and social creed, they remain inseparable, and start raising a hen given to Prakash by his sister, with hopes to save money by selling her eggs. However, the hen goes missing. To find it, they embark on a journey, innocently unaware of the tyranny brought by the fragile ceasefire.', NULL, NULL, 1.8806, 5.964, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
