INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8843, 42544, 'tt0071784', NULL, 'The Stranger and the Gunfighter', 'El Kárate, el Colt y el Impostor', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/9z8QUU352esv2CKD9QRqTfDLW6n.jpg', 'https://image.tmdb.org/t/p/original/uquxTqU6wbgrkHw1SYdNkrJUTBm.jpg', 'During a hold-up in the Wild West, Dakota kills a rich old Chinese man, Wang. Later, he is captured, sentenced, and is about to be hanged - and he never profitted from Wang''s death, has he buried him with the photographs of his four widows, and a few worthless papers. Meanwhile, Ho comes to America in search of his uncle''s fortune, and must get Dakota free, as he his the only man who can lead him to Wang''s tomb. They open the tomb, retaking the pictures of Wang''s widows. It happens he reads the papers and knows that Wang had one quarter of a map tattooed in each of his women''s buttocks. Now, the difficult part will really start... Treasure hunt.', NULL, NULL, 1.7945, 5.37, 0, 1.02, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
