INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8847, 152581, 'tt2484120', NULL, 'Room on the Broom', 'Room on the Broom', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/9qAL19JR0oJ7ZlVpUE1Os2P6XXp.jpg', 'https://image.tmdb.org/t/p/original/h0G3twpMgJsMrPCa4aafial7w1c.jpg', 'Animated film based on the wonderful children''s picture book written by Julia Donaldson and illustrated by Axel Scheffler.  The story of a kind witch who invites a surprising collection of animals to join her on her broom, much to the frustration of her cat. The gang ultimately saves the witch from a fearsome dragon, and in gratitude she rewards them with a magnificent new broom which has room for everyone.  A magical tale about friendship and family from Magic Light Pictures, the producers of the hugely successful The Gruffalo and The Gruffalo''s Child.', NULL, NULL, 2.9693, 6.638, 0, 1.02, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
