INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8854, 109, 'tt0456029', NULL, 'Blue Water High', 'Blue Water High', 'tv', 2005, 'https://image.tmdb.org/t/p/w500/fE8PUhNilYbhjpTfIUy1XJ72BEn.jpg', 'https://image.tmdb.org/t/p/original/1HiRzaRcF7WxTMFnroszv2ICcWj.jpg', 'Blue Water High is an Australian television drama series, broadcast by the Australian Broadcasting Corporation on ABC1 and on Austar/Foxtel Nickelodeon channel in Australia and on various channels in many other countries. Each season follows the lives of a young group of students at Solar Blue, a high-performance surf academy where several lucky 16-year-olds are selected for a 12-month-long surfing program on Sydney''s northern beaches.

There are three series in Blue Water High. The first two series were screened in 2005 and 2006 and the producers did not intend to create a third series. However, due to popular demand by fans, they relented and made one more series with only Kate Bell returning in a main role. Series three ended with the closure of Solar Blue, indicating that the show would most likely not continue.', NULL, NULL, 10.8897, 7.25, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
