INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8883, 7007, 'tt0107969', NULL, 'Rising Sun', 'Rising Sun', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/jVWEeZ383peKxwE284AdyHqq6GH.jpg', 'https://image.tmdb.org/t/p/original/dmaLmrP3PYfhb8P2SWMucZCZqjk.jpg', 'When a prostitute is found dead in a Los Angeles skyscraper occupied by a large Japanese corporation, detectives John Connor and Web Smith are called in to investigate. Although Connor has previous experience working in Japan, cultural differences make their progress difficult until a security disc showing the murder turns up. Close scrutiny proves the disc has been doctored, and the detectives realize they''re dealing with a cover-up as well.', NULL, NULL, 5.6656, 6.139, 0, 1.02, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
