INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8890, 448776, 'tt4080956', NULL, 'A Prayer Before Dawn', 'A Prayer Before Dawn', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/toYs3tZrHbSKJS1hmiTY1fJnPjm.jpg', 'https://image.tmdb.org/t/p/original/euCBYT2HASDMuaxu23yXDuzy3ju.jpg', 'The amazing true story of Billy Moore, an English boxer incarcerated in Thailand’s most notorious prison. Thrown into a world of drugs and violence, he finds his best chance to escape is to fight his way out in prison Muay Thai tournaments.', NULL, NULL, 4.4078, 6.729, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8891, 12277, 'tt0279493', NULL, 'Undercover Brother', 'Undercover Brother', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/vkPm29sqtEjoekOhXbqxTcgpJ4y.jpg', 'https://image.tmdb.org/t/p/original/sxoz5X2wlLrQtY7hSTe1sEnLKfc.jpg', 'An Afro-American organization, the B.R.O.T.H.E.R.H.O.O.D., is in permanent fight against a white organization "The Man" defending the values of the black people in North America. When the Afro-American candidate Gen. Warren Boutwell behaves strangely in his presidential campaign, Undercover Brother is hired to work undercover for "The Man" and find what happened with the potential candidate.', NULL, NULL, 4.4712, 5.918, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8892, 242575, 'tt2876428', NULL, 'Good Day, Ramon', 'Guten Tag, Ramón', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/7xaQAc01TZOHEku2uC520OIENWx.jpg', 'https://image.tmdb.org/t/p/original/1eg3lmXN8BU9NVFBPXiIgK9Tkx9.jpg', 'After five failed attempts to go to the United States, 18-year-old Ramón decides to look for a friend’s aunt in Germany, but never finds her. With no papers or money, and without knowing the language, he barely survives living on the street until he meets Ruth, an old retired nurse who doesn’t speak Spanish. Beyond language barriers and prejudices, they discover that solidarity and humanity make life bearable.', NULL, NULL, 1.4641, 7.894, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8893, 110971, 'tt10801534', NULL, 'How To with John Wilson', 'How To with John Wilson', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/jpHziYpJniprEFDFwMbOHabgnow.jpg', 'https://image.tmdb.org/t/p/original/lnnXNSb3Uk9Y4YWF1Rszyt6tzj0.jpg', 'In a uniquely hilarious odyssey of self-discovery and cultural observation, documentary filmmaker and self-described "anxious New Yorker" John Wilson covertly and obsessively films the lives of his fellow New Yorkers while attempting to give everyday advice on relatable topics. The awkward contradictions of modern life are eased by Wilson’s candid, unpolished commentary. Building upon Wilson’s previously released "how to" short films, each episode takes wildly unexpected turns but is grounded in John''s refreshing honesty.', NULL, NULL, 5.0839, 8.111, 0, 3.08, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8894, 1239655, 'tt30505698', NULL, 'Friendship', 'Friendship', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/eikAu9gPJTQQmwFwa1zX5Hfz96P.jpg', 'https://image.tmdb.org/t/p/original/g70uNy3hRqEcU0ilBTtcuBFlizx.jpg', 'Suburban dad Craig falls hard for his charismatic new neighbor Austin, and his attempts to make an adult male friend threatens to ruin both of their lives.', NULL, NULL, 10.5438, 6.393, 0, 4.08, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8895, 106308, 'tt12759100', NULL, 'Somebody Somewhere', 'Somebody Somewhere', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/1GkoExnlnyTcyGWIoHA4YG8mysc.jpg', 'https://image.tmdb.org/t/p/original/thu4Jh90HdLmI0QXrGlMwyC3bUP.jpg', 'Sam is a true Kansan on the surface but beneath it all struggles to fit the hometown mold. As she grapples with loss and acceptance, singing is Sam’s saving grace and leads her on a journey to discover herself and a community of outsiders that don’t fit in but don’t give up, showing that finding your people, and finding your voice, is possible. Anywhere. Somewhere.', NULL, NULL, 7.5782, 7.169, 0, 3.02666666666666683e+00, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
