INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8897, 17035, 'tt0405163', NULL, 'The Amateurs', 'The Amateurs', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/kj4ZZpyP95ltT4ZF2c6aiyEH5N9.jpg', 'https://image.tmdb.org/t/p/original/A7wROeDATxR28m6oyCYMh4IUKV.jpg', 'Sex sells in America and these guys know it. The Amateurs follows a small town band of loveable losers who hit upon an idea that can make their dreams and fantasies come true. Thinking they''ve found the road to riches and fame they decide to make the world''s most innocent adult film. Everyman''s fantasy turns into a hilarious misadventure when they find they''re in way over their heads.', NULL, NULL, 2.7995, 5.569, 0, 1.03, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8898, 58957, 'tt2297757', NULL, 'Nathan for You', 'Nathan for You', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/6tGXlz61c44onUg6EdRkbhjcaPA.jpg', 'https://image.tmdb.org/t/p/original/5ix5qtVlLR2O0sgAJp5urHLbGZe.jpg', 'Self-proclaimed business expert, writer, director and comedian Nathan Fielder helps real small businesses turn a profit with marketing tactics that no ordinary consultant would dare to attempt. From driving foot traffic to an off-the-strip souvenir shop by using Hollywood flair and a Johnny Depp impersonator, to creating a rebate that can only be redeemed by climbing a mountain, to founding a coffee shop called "Dumb Starbucks,” Nathan has always gone to the limit to make his ideas come to life. With his unorthodox approach to problem solving, Nathan’s genuine efforts to do good often draw the real people he encounters into an experience far beyond what they signed up for.', NULL, NULL, 7.3062, 8.237, 0, 1.03, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
