INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8918, 195, 'tt0023622', NULL, 'Trouble in Paradise', 'Trouble in Paradise', 'movie', 1932, 'https://image.tmdb.org/t/p/w500/FBxuoLRD3Biyul14unT5m3PYNS.jpg', 'https://image.tmdb.org/t/p/original/8xFIubJoxyidKaGjO1dc0btC9e7.jpg', 'Thief Gaston Monescu and pickpocket Lily are partners in crime and love. Working for perfume company executive Mariette Colet, the two crooks decide to combine their criminal talents to rob their employer. Under the alias of Monsieur Laval, Gaston uses his position as Mariette''s personal secretary to become closer to her. However, he takes things too far when he actually falls in love with Mariette, and has to choose between her and Lily.', NULL, NULL, 2.4553, 7.4, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8919, 324552, 'tt4425200', NULL, 'John Wick: Chapter 2', 'John Wick: Chapter 2', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', 'https://image.tmdb.org/t/p/original/r17jFHAemzcWPPtoO0UxjIX0xas.jpg', 'John Wick is forced out of retirement by a former associate looking to seize control of a shadowy international assassins’ guild. Bound by a blood oath to aid him, Wick travels to Rome and does battle against some of the world’s most dangerous killers.', NULL, NULL, 15.0502, 7.342, 0, 12.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8920, 25103, 'tt0050766', NULL, 'Night of the Demon', 'Night of the Demon', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/ePAjGAhynpwEI5HbpIrB28ML6lg.jpg', 'https://image.tmdb.org/t/p/original/bUFWLSQsSYdyy4eohp4iBBnOV1s.jpg', 'American professor John Holden arrives in London for a conference on parapsychology only to discover that the colleague he was supposed to meet was killed in a freak accident the day before. It turns out that the deceased had been investigating a cult lead by Dr. Julian Karswell. Though a skeptic, Holden is suspicious of the devil-worshiping Karswell. Following a trail of mysterious manuscripts, Holden enters a world that makes him question his faith in science.', NULL, NULL, 2.5085, 7.031, 0, 10.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8921, 705996, 'tt12477480', NULL, 'Decision to Leave', '헤어질 결심', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/zI8KZ4EdLUymWKX1YEkpZ0gtPUa.jpg', 'https://image.tmdb.org/t/p/original/A1bWhTFQKkhF1yhSKWosSyzn2Hp.jpg', 'From a mountain peak in South Korea, a man plummets to his death. Did he jump, or was he pushed? When detective Hae-joon arrives on the scene, he begins to suspect the dead man’s wife Seo-rae. But as he digs deeper into the investigation, he finds himself trapped in a web of deception and desire.', NULL, NULL, 9.4285, 7.319, 0, 10.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8922, 10775, 'tt0338564', NULL, 'Infernal Affairs', '無間道', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/gix9thDBXfjJ8M7rYbihqbQGBcP.jpg', 'https://image.tmdb.org/t/p/original/iiDGA97Kqt2dVU1deXQF06USBRu.jpg', 'Chan Wing Yan, a young police officer, has been sent undercover as a mole in the local mafia. Lau Kin Ming, a young mafia member, infiltrates the police force. Years later, their older counterparts, Chen Wing Yan and Inspector Lau Kin Ming, respectively, race against time to expose the mole within their midst.', NULL, NULL, 8.5277, 7.8, 0, 10.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8923, 21734, 'tt0036342', NULL, 'Shadow of a Doubt', 'Shadow of a Doubt', 'movie', 1943, 'https://image.tmdb.org/t/p/w500/ptyWagbWE8jSGyV2tGEzAdVbRCj.jpg', 'https://image.tmdb.org/t/p/original/1p78xI6mywlqhb3tfw6oTJt7X3t.jpg', 'In sleepy Santa Rosa, restless young Charlie’s world brightens when her sophisticated Uncle Charlie arrives for a long visit. But as his behavior grows increasingly strange, she begins to suspect that her beloved uncle may be hiding a terrible secret—and that danger has quietly entered her home.', NULL, NULL, 5.4753, 7.494, 0, 10.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8924, 508138, 'tt8009314', NULL, 'Burn', 'Burn', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/ifSMo5x7SDXpettRt8TWY9EOquM.jpg', 'https://image.tmdb.org/t/p/original/3C14xx4RteMksSUwgYfI52B8Iu6.jpg', 'Lonely, unstable gas station attendant Melinda is tired of being overshadowed by her more confident, outgoing co-worker Sheila. When the gas station is held up at gunpoint by Billy, a desperate man in need of quick cash, Melinda finds an opportunity to make a connection with the robber, regardless of who gets hurt.', NULL, NULL, 4.1713, 6.0, 0, 11.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8925, 524247, 'tt6722030', NULL, 'The Intruder', 'The Intruder', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/p9xKyetr0ihJ2K6HJMeXzc4IwEv.jpg', 'https://image.tmdb.org/t/p/original/kyegg1r5oxRCZgqU7anHYD2TJap.jpg', 'A psychological thriller about a young married couple who buys a beautiful Napa Valley house on several acres of land only to find that the man they bought it from refuses to let go of the property.', NULL, NULL, 5.3453, 6.048, 0, 11.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8926, 813477, 'tt14379088', NULL, 'Shin Kamen Rider', 'シン・仮面ライダー', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/9dTO2RygcDT0cQkawABw4QkDegN.jpg', 'https://image.tmdb.org/t/p/original/ccFavvHGfhA5yI32K0bzDjlyKSN.jpg', 'A man forced to bear power and stripped of humanity. A woman skeptical of happiness. Takeshi Hongo, an Augmentation made by SHOCKER, and Ruriko Midorikawa, a rebel of the organization, escape while fighting off assassins. What’s justice? What’s evil? Will this violence end? Despite his power, Hongo tries to remain human. Along with freedom, Ruriko has regained a heart. What paths will they choose?', NULL, NULL, 4.1689, 7.0, 0, 2.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8927, 194777, 'tt0157028', NULL, 'Shin Kamen Rider: Prologue', '真・仮面ライダー序章', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/204MH13AMvmxR5t7T3I3My7pKfE.jpg', 'https://image.tmdb.org/t/p/original/elwglrpbliKJtmWLFSxPW3ZIojI.jpg', 'Doctors Kazamatsuri and Onizuka are geneticists researching cures on diseases such as AIDS and cancer by performing experiments to strengthen the human body. The test subject is Shin Kazamatsuri, motorcycle racer son of Doctor Kazamatsuri. Unknown to them, their operation is funded by a syndicate group, who plan to use this research to have the bodies of men strengthened for their own gain—they have already been experimenting in the field of cyborg soldiers, to a less-than-successful attempt. However, they did not count on Onizuka''s own secret ambitions; the mad Onizuka wanted to create a new species, by fusing a grasshopper''s DNA with the test subject''s, in order to start a new civilization and be their god. He has tested on himself, but seems to be having greater success with Shin.', NULL, NULL, 1.614, 6.2, 0, 2.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8928, 187922, 'tt0099917', NULL, 'Kamen Rider ZO', '仮面ライダーZO', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/lzDXr6naEa4Pcd23B9fZP8zmnMc.jpg', 'https://image.tmdb.org/t/p/original/7j82LXjT3mQczJRpUL9RLP9yyCj.jpg', 'Masaru Aso was the lab assistant of geneticist Doctor Mochizuki, used as one of his experiments related the creation of the Neo Organism, enabling him to transform into a grasshopper-like being called Kamen Rider ZO. He fled into the mountainside and went into a coma before he was awakened by a telepathic call two years later with an unconscious urge to protect Hiroshi Mochizuki, the son of Doctor Mochizuki.', NULL, NULL, 1.8525, 7.318, 0, 4.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8929, 185958, 'tt0156670', NULL, 'Kamen Rider J', '仮面ライダーJ', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/eigCNQq0EI9ojtdBzbpmvuoFugW.jpg', 'https://image.tmdb.org/t/p/original/dnjoSQMIUIymAJ7NW2jjKvyKvhy.jpg', 'The story begins with three Aliens in human form preparing for a ritual to feed the Fog Mother''s "siblings". The Fog Mother last came to earth during the Prehistoric Age and is the cause of the extinction of the dinosaurs. Kenji and his kid sister are in the mountains, investigating all the deaths of animals and trees there. The Fog Mother sends the three aliens, "Gorai", "Zuu", and "Agito" to kidnap Kenji''s baby sister for the sacrifice.', NULL, NULL, 1.5746, 6.656, 0, 3.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8930, 62877, 'tt0111822', NULL, 'Zëiram 2', 'ゼイラム 2', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/yPUlS9EYfNlVgwSKX1RQAnfsGOO.jpg', 'https://image.tmdb.org/t/p/original/lg8rWZF7kb6209Kb5oGvrIbkoZz.jpg', 'Intergalactic bounty hunters Iria and Bob return to track down an ancient mystical relic. When a second Zeiram unit shows up and goes berserk, it takes all of Iria''s resources to survive a deadly game of cat-and-mouse with the fearsome space creature.', NULL, NULL, 1.5951, 6.531, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8931, 15026, 'tt0101988', NULL, 'The Guyver', 'The Guyver', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/g4RYPu0ewWd5XIbPZPpfLpsMgp3.jpg', 'https://image.tmdb.org/t/p/original/kVU8aXUODqdcNs6xS2SgBv61jaz.jpg', 'FBI agent Max Reed witnesses Dr. Tetsu Segawa - a researcher for the mysterious Chronos Corporation - being murdered. Dr. Segawa had stolen an alien device known as "The Guyver" from Chronos. College student Sean Barker, whose girlfriend''s father was Dr. Segawa, finds the Guyver''s hiding spot while watching the forensic team investigating the crime scene.', NULL, NULL, 2.9653, 5.583, 0, 9.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8932, 1941, 'tt0978032', NULL, 'GARO', '牙狼＜GARO＞', 'tv', 2005, 'https://image.tmdb.org/t/p/w500/3IBGi1F4oRlykR0k9beIwygn8YM.jpg', 'https://image.tmdb.org/t/p/original/mvi2YbFePpq68xaHEwezpmSEdsv.jpg', 'The Makai fight a secret war against the demon forces known as Horrors, evil creatures that manifest themselves through darkness to devour Humanity. On the frontlines are the Makai Knights, given the task of watching over a district and eliminating any Horrors that manifest there.

GARO follows the tales of the Knights bearing the title of ‘Golden Knight Garo’, and their duty to vanquish the Horrors and protect Humanity from the darkness.', NULL, NULL, 31.3706, 7.7, 0, 2.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
