INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8939, 7246, 'tt0084988', NULL, 'Blackadder', 'Blackadder', 'tv', 1983, 'https://image.tmdb.org/t/p/w500/y3rXOeklqhZ7BTBveW5WLJqyjgU.jpg', 'https://image.tmdb.org/t/p/original/ArLn4fRjLqqMtyPTB22qaTK4Cxt.jpg', 'Blackadder traces the deeply cynical and self-serving lineage of various Edmund Blackadders throughout British history, from the muck of the Middle Ages to the frontline of The Great War.', NULL, NULL, 18.4933, 7.977, 0, 11.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8940, NULL, NULL, 1009, 'The Last of Us', 'The Last of Us', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7f.jpg', NULL, 'The Last of Us is a third-person action-adventure game featuring a mix of exploration, stealth and combat. Players face both infected creatures and hostile human enemies while progressing through varied environments. The game includes a narrative-driven single-player campaign and a competitive online multiplayer mode called Factions. Trophy support is included, and additional downloadable content was made available separately.', 'https://www.igdb.com/games/the-last-of-us', '["PlayStation 3"]', NULL, NULL, 0, 8.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8941, NULL, NULL, 17, 'Fallout Tactics: Brotherhood of Steel', 'Fallout Tactics: Brotherhood of Steel', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ybr.jpg', NULL, 'This is a Tactical Squad-Based Combat comes to the Fallout Universe. You are the wretched refuse. You may be born from dirt, but we will forge you into steel. You will learn to bend; if not you, will you break. In these dark times, the Brotherhood - your Brotherhood - is all that stands between the rekindled flame of civilization and the howling, radiated wasteland.

Your weapons will become more than your tools, they will become your friends. You will use your skills to inspire the lowly and protect the weak... whether they like it or not. Your squadmates will be more dear to you than your kin and for those that survive there will be honor, respect and the spoils of war.', 'https://www.igdb.com/games/fallout-tactics-brotherhood-of-steel', '["PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 10.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
