INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8964, 211624, 'tt12963502', NULL, 'Families Like Ours', 'Familier som vores', 'tv', 2024, 'https://image.tmdb.org/t/p/w500/2S7KqteoupMp1ivg7pp0bp0E9Qv.jpg', 'https://image.tmdb.org/t/p/original/wvwCIPcT08TLi9DbO1zn8dRPWpF.jpg', 'In a not-too-distant future, Denmark faces total evacuation due to rising water levels. As the nation prepares to leave their homes, high school student Laura must choose between her divorced parents and the boy she''s fallen in love with.', NULL, NULL, 4.4604, 7.1, 0, 9.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8965, 420821, 'tt3513500', NULL, 'Chip ''n Dale: Rescue Rangers', 'Chip ''n Dale: Rescue Rangers', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/7UGmn8TyWPPzkjhLUW58cOUHjPS.jpg', 'https://image.tmdb.org/t/p/original/qK7Ssnrfvrt65F66A1thvehfQg2.jpg', 'Decades since their successful television series was canceled, Chip has succumbed to a life of suburban domesticity as an insurance salesman. Dale, meanwhile, has had CGI surgery and works the nostalgia convention circuit, desperate to relive his glory days. When a former cast mate mysteriously disappears, Chip and Dale must repair their broken friendship and take on their Rescue Rangers detective personas once again to save their friend’s life.', NULL, NULL, 7.5632, 6.983, 0, 10.51, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8966, 47979, 'tt1611211', NULL, 'Vincent Wants to Sea', 'Vincent will Meer', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/lGJUOYiOLrhk4p9SmQNT6qIX155.jpg', 'https://image.tmdb.org/t/p/original/bcX3U1VTbreXzpOblmK0KhEbC8E.jpg', 'Vincent, a young man who suffers from Tourette''s syndrome, has just lost his mother. His father, a successful politician, does not want to take care of him and therefore places him into a mental institution. He is put into a room with Alexander, a guy with a compulsive disorder, and is shown around by Marie, an anorectic girl.', NULL, NULL, 1.6099, 6.72, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8967, 57138, 'tt0265548', NULL, 'A Summer in a Sea Shell', 'Poletje v školjki', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/cnDfNni4YdIP53cMIMD8Zb4W4fm.jpg', 'https://image.tmdb.org/t/p/original/ue6JpO4bCVFrY7Amu1L72EWEhPw.jpg', 'Young Tomaž has many problems. Not only is he quite lonely, but he also has to leave his hometown and move to the city with his family because of his father''s new job. In these difficult times, his only help is his computer Vedi. Even disputes between local gangs can not solve any problems, at least not until both gangs get a common enemy - motorcyclists who steal shells.', NULL, NULL, 0.6205, 7.8, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8968, 177221, 'tt2272350', NULL, 'The Battery', 'The Battery', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/nI7lzx2t4UPfuqhunB5bEVymOOV.jpg', 'https://image.tmdb.org/t/p/original/4cjH6b7MGJssyYNNntog1YZZ9CJ.jpg', 'In rural Connecticut, baseball players Ben and Mickey are trying to survive a zombie plague. They are forced to form a battery: a catcher and a pitcher who work together to outwit the batter, the one who hits the ball. And the batter in this case just happens to be a zombie. Tough Ben and gentle Mickey frequently disagree on the best way to go about the situation. Then they suddenly hear a human voice through their walkie-talkies. Is salvation nearby, like Mickey thinks, or is Ben’s suspicion justified?', NULL, NULL, 3.0519, 6.125, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
