INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8971, 38360, 'tt0050634', NULL, 'The Cranes Are Flying', 'Летят журавли', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/foXYOdXEJ0rvtTDo4LLnsUnvPLB.jpg', 'https://image.tmdb.org/t/p/original/r6bIGLFJ2ml9L970RNpuwDyb4Af.jpg', 'Veronika and Boris come together in Moscow shortly before World War II. Walking along the river, they watch cranes fly overhead, and promise to rendezvous before Boris leaves to fight. Boris misses the meeting and is off to the front lines, while Veronika waits patiently, sending letters faithfully. After her house is bombed, Veronika moves in with Boris'' family, into the company of a cousin with his own intentions.', NULL, NULL, 4.3196, 7.91, 0, 1.01, '2026-08-10 02:34:01', '2026-08-10 02:34:01');
