UPDATE "recommendations" SET "tmdb_id"=13460, "imdb_id"='tt0483607', "igdb_id"=NULL, "title"='Doomsday', "original_title"='Doomsday', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/cKUmTyXgmhv8cMRCY9RYTKcAeTn.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2GmnhciVW262POiTCx43TTSvys3.jpg', "overview"='The lethal Reaper virus spreads throughout Britain—infecting millions and killing hundreds of thousands. Authorities brutally and successfully quarantine the country but, three decades later, the virus resurfaces in a major city. An elite group of specialists is urgently dispatched into the still-quarantined country to retrieve a cure by any means necessary. Shut off from the rest of the world, the unit must battle through a landscape that has become a waking nightmare.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2189, "vote_average"=5.938, "is_ambiguous"=0, "evidence_score"=11.2775, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=746;
