UPDATE "recommendations" SET "tmdb_id"=345, "imdb_id"='tt0120663', "igdb_id"=NULL, "title"='Eyes Wide Shut', "original_title"='Eyes Wide Shut', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/knEIz1eNGl5MQDbrEAVWA7iRqF9.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aC6wW62V6b0csr5iUnbOjYAqfhg.jpg', "overview"='After Dr. Bill Harford''s wife, Alice, admits to having sexual fantasies about a man she met, Bill becomes obsessed with having a sexual encounter. He discovers an underground sexual group and attends one of their meetings -- and quickly discovers that he is in over his head.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.5573, "vote_average"=7.486, "is_ambiguous"=0, "evidence_score"=3.35003333333333372e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=772;
UPDATE "recommendations" SET "tmdb_id"=5548, "imdb_id"='tt0093870', "igdb_id"=NULL, "title"='RoboCop', "original_title"='RoboCop', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xcaX6BZ1JUPSVMH2gBkWIckLLaA.jpg', "overview"='In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3779, "vote_average"=7.364, "is_ambiguous"=0, "evidence_score"=2.19719999999999977e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=777;
UPDATE "recommendations" SET "tmdb_id"=11309, "imdb_id"='tt0099740', "igdb_id"=NULL, "title"='Hardware', "original_title"='Hardware', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/ybauOsdo6ColZ1WsALqIYjpUg4X.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nC1qaINaRBY1crPCQoFVPhSrq16.jpg', "overview"='Mark 13 is a government-built killing machine programmed with artificial intelligence, able to repair and recharge itself from any energy source. Through a series of coincidences, the cyborg''s head ends up in the home of a sculptress as a bizarre Christmas present from her boyfriend. Once inside its new home, the cyborg promptly reconstructs the rest of its body using a variety of household utensils and proceeds to go on a murderous rampage.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.9931, "vote_average"=5.9, "is_ambiguous"=0, "evidence_score"=13.8975, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=782;
UPDATE "recommendations" SET "tmdb_id"=9886, "imdb_id"='tt0113481', "igdb_id"=NULL, "title"='Johnny Mnemonic', "original_title"='Johnny Mnemonic', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/iH8Jgi8qvb7pnBfI8fVGaUbyRna.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7FRYVIF2hnh1IbPtqMgF5iygdjz.jpg', "overview"='In a dystopian 2021, Johnny is a data trafficker who has an implant that allows him to securely store data too sensitive for regular computer networks. On one delivery run, he accepts a package that not only exceeds the implant''s safety limits—and will kill him if the data is not removed in time—but also contains information far more important and valuable than he had ever imagined. On a race against time, he must avoid the assassins sent to kill him and remove the data before it, too, ends his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3516, "vote_average"=5.758, "is_ambiguous"=0, "evidence_score"=17.28, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=785;
