UPDATE "recommendations" SET "tmdb_id"=5544, "imdb_id"='tt0052893', "igdb_id"=NULL, "title"='Hiroshima Mon Amour', "original_title"='Hiroshima mon amour', "media_type"='movie', "release_year"=1959, "poster_url"='https://image.tmdb.org/t/p/w500/zieczjWnvalaxwX5EQASEx0on5f.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4fynFAYPPYCkyIdt0bsCwWn3Hxv.jpg', "overview"='The deep conversation between a Japanese architect and a French actress forms the basis of this celebrated French film, considered one of the vanguard productions of the French New Wave. Set in Hiroshima after the end of World War II, the couple -- lovers turned friends -- recount, over many hours, previous romances and life experiences. The two intertwine their stories about the past with pondering the devastation wrought by the atomic bomb dropped on the city.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3778, "vote_average"=7.67, "is_ambiguous"=0, "evidence_score"=11.51, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1112;
