UPDATE "recommendations" SET "tmdb_id"=854, "imdb_id"='tt0110475', "igdb_id"=NULL, "title"='The Mask', "original_title"='The Mask', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bQlw59HncOXX9alFlOYKHAvSnm.jpg', "overview"='Timid bank clerk Stanley Ipkiss discovers a magical mask infused with the spirit of the Norse god Loki. Donning it transforms him into an unrestrained, green-faced, cartoon-like wild man. While the mask grants him the confidence to woo a local singer, it also makes him the target of a ruthless mobster.', "external_url"=NULL, "platforms"=NULL, "popularity"=18.4885, "vote_average"=6.995, "is_ambiguous"=0, "evidence_score"=10.855, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1237;
UPDATE "recommendations" SET "tmdb_id"=14239, "imdb_id"='tt0104009', "igdb_id"=NULL, "title"='Cool World', "original_title"='Cool World', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/mqzRUHNtFwmgJCmSnvq3JnX0xgZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uRUAwzXOU75vmO0CD1RzY0CaZ8d.jpg', "overview"='While incarcerated for murder, cartoonist Jack Deebs found escape by creating Cool World, a series featuring a voluptuous femme fatale named Holli Would. But the artist becomes a prisoner of his own fantasies when Holli transports Jack into Cool World with a scheme to seduce him and bring herself to life. Hard-boiled detective Frank Harris – the only other human in Cool World – cautions Jack with the law: Noids (humans) don''t have sex with doodles (cartoons). However, flesh proves weaker than ink as Holli takes human form in Las Vegas, staring in a trans-universal chase that threatens the destruction of both worlds.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.9505, "vote_average"=5.7, "is_ambiguous"=0, "evidence_score"=1.86828571428571414e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1238;
