UPDATE "recommendations" SET "tmdb_id"=607, "imdb_id"='tt0119654', "igdb_id"=NULL, "title"='Men in Black', "original_title"='Men in Black', "media_type"='movie', "release_year"=1997, "poster_url"='https://image.tmdb.org/t/p/w500/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/o9puyKpayQoX8ikIaYtf2PfKv3.jpg', "overview"='After a police chase with an otherworldly being, a New York City cop is recruited as an agent in a top-secret organization established to monitor and police alien activity on Earth: the Men in Black. Agent K and new recruit Agent J find themselves in the middle of a deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.7757, "vote_average"=7.225, "is_ambiguous"=0, "evidence_score"=1.44050000000000011e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1940;
UPDATE "recommendations" SET "tmdb_id"=1487, "imdb_id"='tt0167190', "igdb_id"=NULL, "title"='Hellboy', "original_title"='Hellboy', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/lbaTEneOofwvAyg77R8HbFML2zT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/avwEj8wiywFH6FZ6h2wzvyJpiH7.jpg', "overview"='In the final days of World War II, the Nazis attempt to use black magic to aid their dying cause. The Allies raid the camp where the ceremony is taking place, but not before they summon a baby demon who is rescued by Allied forces and dubbed "Hellboy". Sixty years later, Hellboy serves the cause of good rather than evil as an agent in the Bureau of Paranormal Research & Defense, along with Abe Sapien - a merman with psychic powers, and Liz Sherman - a woman with pyrokinesis, protecting America against dark forces.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.3798, "vote_average"=6.677, "is_ambiguous"=0, "evidence_score"=2.38283333333333331e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1942;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=538, "title"='BioShock Infinite', "original_title"='BioShock Infinite', "media_type"='game', "release_year"=2013, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2n12.jpg', "backdrop_url"=NULL, "overview"='BioShock Infinite is the third game in the BioShock series. It is not a direct sequel/prequel to any of the previous BioShock games but takes place in an entirely different setting, although it shares similar features, gameplay and concepts with the previous games. BioShock Infinite features a range of environments that force the player to adapt, with different weapons and strategies for each situation. Interior spaces feature close combat with enemies, but unlike previous games set in Rapture, the setting of Infinite contains open spaces with emphasis on sniping and ranged combat against as many as fifteen enemies at once.', "external_url"='https://www.igdb.com/games/bioshock-infinite', "platforms"='["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=7.0125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-10 02:34:01' WHERE "id"=1944;
