UPDATE "recommendations" SET "tmdb_id"=14361, "imdb_id"='tt0103924', "igdb_id"=NULL, "title"='Captain Ron', "original_title"='Captain Ron', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/otnKFXvqFH2swlrNf2sNiXpnIsR.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cUqa9ngoI72dFGVQKVLsTbzj65B.jpg', "overview"='When mild-mannered Martin Harvey finds out that he has inherited a vintage yacht, he decides to take his family on a Caribbean vacation to retrieve the vessel. Upon arriving on a small island and realizing that the ship is in rough shape, Martin and his family end up with more than they bargained for as the roguish Captain Ron signs on to sail the boat to Miami. It doesn''t take long before Ron''s anything-goes antics get the Harveys into plenty of trouble.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5511, "vote_average"=5.593, "is_ambiguous"=0, "evidence_score"=11.385, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-10 02:34:01' WHERE "id"=3458;
