UPDATE "recommendations" SET "tmdb_id"=1824, "imdb_id"='tt0343660', "igdb_id"=NULL, "title"='50 First Dates', "original_title"='50 First Dates', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v8lPo8UWKyP2tIXD8N64HfNP4Pw.jpg', "overview"='Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it''s possible to fall in love all over again…and again, and again. That''s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.5692, "vote_average"=6.9, "is_ambiguous"=0, "evidence_score"=10.31875, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-10 02:34:01' WHERE "id"=3467;
