UPDATE "recommendations" SET "tmdb_id"=58431, "imdb_id"='tt1374989', "igdb_id"=NULL, "title"='Pride and Prejudice and Zombies', "original_title"='Pride and Prejudice and Zombies', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/jsJlOhVHiz1xXr36616EI8tJ4b2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld9gXxcJoc1JF0SriRiHvIdK6yh.jpg', "overview"='A zombie outbreak has fallen upon the land in this reimagining of Jane Austen''s classic tale of the tangled relationships between lovers from different social classes in 19th century England. Feisty heroine Elizabeth Bennet is a master of martial arts and weaponry and the handsome Mr. Darcy is a fierce zombie killer, yet the epitome of upper class prejudice. As the zombie outbreak intensifies, they must swallow their pride and join forces on the blood-soaked battlefield in order to conquer the undead once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6264, "vote_average"=6.164, "is_ambiguous"=0, "evidence_score"=9.0075, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-10 02:34:01' WHERE "id"=3675;
