UPDATE "recommendations" SET "tmdb_id"=409421, "imdb_id"='tt6574146', "igdb_id"=NULL, "title"='BLAME!', "original_title"='ブラム', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/7eoRQY7VUMawwBnuD6uwN4szc8k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9orgGrjh0Jivz0zZLn1Ufj4NRZP.jpg', "overview"='In the distant technological future, civilization has reached its ultimate Net-based form. An "infection" in the past caused the automated systems to spiral out of order, resulting in a multi-leveled city structure that replicates itself infinitely in all directions. Now humanity has lost access to the city''s controls, and is hunted down and purged by the defense system known as the Safeguard. In a tiny corner of the city, a little enclave known as the Electro-Fishers is facing eventual extinction, trapped between the threat of the Safeguard and dwindling food supplies. A girl named Zuru goes on a journey to find food for her village, only to inadvertently cause doom when an observation tower senses her and summons a Safeguard pack to eliminate the threat. With her companions dead and all escape routes blocked, the only thing that can save her now is the sudden arrival of Killy the Wanderer, on his quest for the Net Terminal Genes, the key to restoring order to the world.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5604, "vote_average"=6.54, "is_ambiguous"=0, "evidence_score"=1.07199999999999988e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-10 02:34:01' WHERE "id"=3694;
