UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=6801, "title"='Far Cry 4', "original_title"='Far Cry 4', "media_type"='game', "release_year"=2014, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2npa.jpg', "backdrop_url"=NULL, "overview"='Discover the most diverse Far Cry world ever created. With terrain spanning from lush forests to the snowcapped Himalayas, the entire world is alive… and deadly. From leopards, rhinos, black eagles, and vicious honey badgers, Kyrat is home to abundant wildlife. As you embark on your hunt for resources, know that something may be hunting you...

