UPDATE "recommendations" SET "tmdb_id"=279977, "imdb_id"='tt3547900', "igdb_id"=NULL, "title"='The Mirror', "original_title"='The Mirror', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/n1pUEQuhju702gfA0XGsZz0nBNV.jpg', "backdrop_url"=NULL, "overview"='There is a long-held belief that mirrors act as gateways to another dimension. ·Some also believe the looking glass plays host to a world filled with evil spirits. Such superstition has been the basis for ancient folklore legends about haunting and possession. And one tale about a supposedly haunted mirror was picked up by the media in 2012. Both the Daily Mail and Huffington Post reported on how the owners of a recently purchased antique mirror left them dogged by bad luck, financial misery, strange sightings and death-defying illness. Now writer/director Edward Boase brings that horrifying story to the screen starring Jemma Dallender (I SPIT ON YOUR GRAVE 2), Joshua Dickinson and Nate Fallows (‘Whitechapel’) as flatmates who buy the same eerie antique on ebay and set up round the clock cameras in the hopes of capturing evidence of bumps in the night. You have been warned!', "external_url"=NULL, "platforms"=NULL, "popularity"=0.8787, "vote_average"=4.188, "is_ambiguous"=0, "evidence_score"=9.01333333333333364e+00, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-10 02:34:01' WHERE "id"=5027;
